133	/****************************************************************************
134	 * Name: mld_catfile
135	 *
136	 * Description:
137	 *   Dump the contents of a file to the current NSH terminal.
138	 *
139	 * Input Paratemets:
140	 *   filepath - The path to the file to dump
141	 *   iobuffer - An I/O buffer to use for the data transfer
142	 *
143	 * Returned Value:
144	 *   None
145	 *
146	 ****************************************************************************/
147	
148	#if defined(HAVE_PROC_NET_STATS) || defined(HAVE_PROC_NET_ROUTE)
149	void mld_catfile(FAR const char *filepath, FAR char **iobuffer)
150	{
151	  int fd;
152	
153	  /* Open the file for reading.
154	   * REVISIT: Assume procfs is mounted at /proc
155	   */
156	
157	  fd = open(filepath, O_RDONLY);
158	  if (fd < 0)
159	    {
160	      fprintf(stderr, "Failed to open %s:  %d\n", filepath, errno);
161	      return;
162	    }
163	
164	  if (*iobuffer == NULL)
165	    {
166	      *iobuffer = (FAR char *)malloc(IOBUFFERSIZE);
167	      if (*iobuffer == NULL)
168	        {
169	          close(fd);
170	          fprintf(stderr, "Failed to allocation I/O buffer\n");
171	          return;
172	        }
173	    }
174	
175	  /* And just dump it byte for byte into stdout */
176	
177	  for (; ; )
178	    {
179	      ssize_t nbytesread = read(fd, *iobuffer, IOBUFFERSIZE);
180	
181	      /* Check for read errors */
182	
183	      if (nbytesread < 0)
184	        {
185	          int errval = errno;
186	
187	          if (errval == EINTR)
188	            {
189	              continue;
190	            }
191	
192	          fprintf(stderr, "Read from %s failed:  %d\n", filepath, errval);
193	          return;
194	        }
195	
196	      /* Check for data successfully read */
197	
198	      else if (nbytesread > 0)
199	        {
200	          int nbyteswritten = 0;
201	
202	          while (nbyteswritten < nbytesread)
203	            {
204	              ssize_t n = write(1, *iobuffer, nbytesread);
205	              if (n < 0)
206	                {
207	                  int errval = errno;
208	
209	                  if (errval == EINTR)
210	                    {
211	                      continue;
212	                    }
213	
214	                  fprintf(stderr, "Write to stdout failed:  %d\n", errval);
215	                  return;
216	                }
217	              else
218	                {
219	                  nbyteswritten += n;
220	                }
221	            }
222	        }
223	
224	      /* Otherwise, it is the end of file */
225	
226	      else
227	        {
228	          break;
229	        }
230	    }
231	
232	  close(fd);
233	}
234	#endif
