255	
256	int main(int argc, FAR char *argv[])
257	{
258	  FAR char *iobuffer = NULL;
259	  struct sockaddr_in6 host;
260	#ifdef CONFIG_NET_ROUTE
261	  struct sockaddr_in6 target;
262	  struct sockaddr_in6 router;
263	  struct sockaddr_in6 netmask;
264	#endif
265	  struct ipv6_mreq mrec;
266	  int nsec;
267	  int sockfd;
268	  int ret;
269	
270	#ifdef CONFIG_EXAMPLES_MLD_INIT
271	#ifdef CONFIG_EXAMPLES_MLD_NOMAC
272	  uint8_t mac[IFHWADDRLEN];
273	#endif
274	
275	  printf("Configuring Ethernet...\n");
276	
277	#ifdef CONFIG_EXAMPLES_MLD_NOMAC
278	  /* Many embedded network interfaces must have a software assigned MAC */
279	
280	  mac[0] = 0x00;
281	  mac[1] = 0xe0;
282	  mac[2] = 0xde;
283	  mac[3] = 0xad;
284	  mac[4] = 0xbe;
285	  mac[5] = 0xef;
286	  netlib_setmacaddr("eth0", mac);
287	#endif
288	
289	  /* Set up our (fixed) host address */
290	
291	  netlib_set_ipv6addr("eth0", (FAR const struct in6_addr *)g_host_addr);
292	
293	  /* Set up the default router address */
294	
295	  netlib_set_dripv6addr("eth0", (FAR const struct in6_addr *)g_dr_addr);
296	
297	  /* Setup the subnet mask */
298	
299	  netlib_set_ipv6netmask("eth0", (FAR const struct in6_addr *)g_netmask);
300	
301	  /* Bring the network up */
302	
303	  netlib_ifup("eth0");
304	#endif /* CONFIG_EXAMPLES_MLD_INIT */
305	
306	  memset(&host, 0, sizeof(struct sockaddr_in6));
307	  host.sin6_family  = AF_INET6;
308	  sockfd            = socket(PF_INET6, SOCK_DGRAM, 0);
309	  if (sockfd < 0)
310	    {
311	      fprintf(stderr, "ERROR: socket() failed: %d\n", errno);
312	      return EXIT_FAILURE;
313	    }
314	
315	  /* Join the group */
316	
317	  printf("Join group...\n");
318	  mld_dumpstats(&iobuffer);
319	
320	  memcpy(mrec.ipv6mr_multiaddr.s6_addr16,
321	         g_grp_addr, sizeof(struct in6_addr));
322	  mrec.ipv6mr_interface = if_nametoindex("eth0");
323	
324	  ret = setsockopt(sockfd, IPPROTO_IPV6, IPV6_JOIN_GROUP, (FAR void *)&mrec,
325	                   sizeof(struct ipv6_mreq));
326	  if (ret < 0)
327	    {
328	      fprintf(stderr, "ERROR: setsockopt() failed: %d\n", errno);
329	      ret = EXIT_FAILURE;
330	      goto errout_with_socket;
331	    }
332	
333	  /* Wait a while.  Here is assume you are monitoring the network traffic
334	   * with a tool like WireShark.  This is what you should expect after the
335	   * join (assuming default values for MLD delay and count settings):
336	   *
337	   * 1. A outgoing Report message immediately upon joining.
338	   * 2. Another Report message after a delay of 1 second
339	   * 3. Thereafter, periodic Query messages separated by delays of
340	   *    125 seconds
341	   *
342	   * So the following delay is set so that we can verify all of the possible
343	   * timed events.
344	   */
345	
346	  printf("Waiting 300 seconds...\n");
347	  mld_dumpstats(&iobuffer);
348	
349	  for (nsec = 0; nsec < 300; nsec += 10)
350	    {
351	      sleep(10);
352	      printf("\nElapsed: %d sec\n", nsec + 10);
353	      mld_dumpstats(&iobuffer);
354	    }
355	
356	#ifdef CONFIG_NET_ROUTE
357	  printf("\nSet up route for the multicast address...\n");
358	  mld_dumproute(&iobuffer);
359	
360	  /* Set up a routing table entry for the address of the multicast group */
361	
362	  memset(&target, 0, sizeof(target));
363	  target.sin6_family  = AF_INET6;
364	  target.sin6_port    = HTONS(0x4321);
365	  memcpy(v6_addr->sin6_addr.s6_addr16, g_grp_addr, sizeof(struct in6_addr));
366	
367	  memset(&netmask, 0, sizeof(netmask));
368	  netmask.sin6_family  = AF_INET6;
369	  netmask.sin6_port    = HTONS(0x4321);
370	  memset(v6_addr->sin6_addr.s6_addr16, 0xff, sizeof(struct in6_addr));
371	
372	  memset(&router, 0, sizeof(router));
373	  router.sin6_family  = AF_INET6;
374	  router.sin6_port    = HTONS(0x4321);
375	
376	  ret = netlib_get_ipv6addr("eth0", &v6_addr->sin6_addr);
377	  if (ret < 0)
378	    {
379	      fprintf(stderr, "ERROR: netlib_get_ipv6addr() failed: %d\n", ret);
380	    }
381	  else
382	    {
383	      ret = addroute(sockfd, &target, &netmask, &router, sizeof(router));
384	      if (ret < 0)
385	        {
386	          fprintf(stderr, "ERROR: addroute() failed: %d\n", errno);
387	        }
388	    }
389	
390	  mld_dumproute(&iobuffer);
391	
392	  if (ret >= 0)
393	    {
394	      /* Send a garbage packet */
395	
396	      ret = sendto(sockfd, g_garbage, sizeof(g_garbage), 0,
397	                   (FAR struct sockaddr *)&target,
398	                   sizeof(struct sockaddr_in6));
399	      if (ret < 0)
400	        {
401	          fprintf(stderr, "ERROR: sendto() failed: %d\n", errno);
402	        }
403	    }
404	
405	  ret = delroute(sockfd, &target, &netmask, sizeof(target));
406	  if (ret < 0)
407	    {
408	      fprintf(stderr, "ERROR: delroute() failed: %d\n", errno);
409	    }
410	
411	  mld_dumproute(&iobuffer);
412	
413	  /* Wait a while */
414	
415	  printf("Wait a bit...\n");
416	  sleep(5);
417	  mld_dumpstats(&iobuffer);
418	#endif
419	
420	  /* Leave the group */
421	
422	  printf("Leave group...\n");
423	  ret = setsockopt(sockfd, IPPROTO_IPV6, IPV6_LEAVE_GROUP, (FAR void *)&mrec,
424	                   sizeof(struct ipv6_mreq));
425	  if (ret < 0)
426	    {
427	      fprintf(stderr, "ERROR: setsockopt() failed: %d\n", errno);
428	      ret = EXIT_FAILURE;
429	      goto errout_with_socket;
430	    }
431	
432	  /* Wait a while.  Here we should see a Done message sent immediately
433	   * when leaving the group.
434	   */
435	
436	  mld_dumpstats(&iobuffer);
437	  printf("Wait a bit...\n");
438	  sleep(5);
439	
440	  mld_dumpstats(&iobuffer);
441	  printf("Exiting...\n");
442	  ret = EXIT_SUCCESS;
443	
444	errout_with_socket:
445	  close(sockfd);
446	  if (iobuffer != NULL)
447	    {
448	      free(iobuffer);
449	    }
450	
451	  return ret;
452	}
