40	using PersonDetectionOpResolver = MicroMutableOpResolver<6>;
41	using PersonDetectionBenchmarkRunner = MicroBenchmarkRunner<int8_t>;
42	
43	// Create an area of memory to use for input, output, and intermediate arrays.
44	// Align arena to 16 bytes to avoid alignment warnings on certain platforms.
45	constexpr int kTensorArenaSize = 135 * 1024;
46	alignas(16) uint8_t tensor_arena[kTensorArenaSize];
47	
48	uint8_t op_resolver_buffer[sizeof(PersonDetectionOpResolver)];
49	uint8_t benchmark_runner_buffer[sizeof(PersonDetectionBenchmarkRunner)];
50	
51	// Initialize benchmark runner instance explicitly to avoid global init order
52	// issues on Sparkfun. Use new since static variables within a method
53	// are automatically surrounded by locking, which breaks bluepill.
54	PersonDetectionBenchmarkRunner* CreateBenchmarkRunner(MicroProfiler* profiler) {
55	  // We allocate PersonDetectionOpResolver from a global buffer
56	  // because the object's lifetime must exceed that of the
57	  // PersonDetectionBenchmarkRunner object.
58	  PersonDetectionOpResolver* op_resolver =
59	      new (op_resolver_buffer) PersonDetectionOpResolver();
60	  op_resolver->AddFullyConnected(tflite::Register_FULLY_CONNECTED_INT8());
61	  op_resolver->AddConv2D(tflite::Register_CONV_2D_INT8REF());
62	  op_resolver->AddDepthwiseConv2D();
63	  op_resolver->AddSoftmax();
64	  op_resolver->AddAveragePool2D(tflite::Register_AVERAGE_POOL_2D_INT8());
65	  op_resolver->AddReshape();
66	  return new (benchmark_runner_buffer)
67	      PersonDetectionBenchmarkRunner(g_person_detect_model_data, op_resolver,
68	                                     tensor_arena, kTensorArenaSize, profiler);
69	}
70	
71	void PersonDetectionNIerations(const int8_t* input, int iterations,
72	                               const char* tag,
73	                               PersonDetectionBenchmarkRunner& benchmark_runner,
74	                               MicroProfiler& profiler) {
75	  benchmark_runner.SetInput(input);
76	  uint32_t ticks = 0;
77	  for (int i = 0; i < iterations; ++i) {
78	    profiler.ClearEvents();
79	    benchmark_runner.RunSingleIteration();
80	    ticks += profiler.GetTotalTicks();
81	  }
82	  MicroPrintf("%s took %u ticks (%u ms)", tag, ticks, TicksToMs(ticks));
83	}
