236	
237	          dst[x] = ((clamp8(y0 + ((179 * v) >> 7)) & 0xf8) << 8) |
238	                   ((clamp8(y0 - ((44 * u) >> 7) - ((91 * v) >> 7)) & 0xfc) << 3) |
239	                   (clamp8(y0 + ((227 * u) >> 7)) >> 3);
240	
241	          dst[x + 1] = ((clamp8(y1 + ((179 * v) >> 7)) & 0xf8) << 8) |
242	                       ((clamp8(y1 - ((44 * u) >> 7) - ((91 * v) >> 7)) & 0xfc) << 3) |
243	                       (clamp8(y1 + ((227 * u) >> 7)) >> 3);
244	
245	          src += 4;
246	        }
247	    }
248	
249	  fb_blit(cpw, cph);
250	}
