56	 * Pre-processor Definitions
57	 ****************************************************************************/
58	
59	/* Model input parameters (from person_detect model training) */
60	
61	#define NUM_COLS       96
62	#define NUM_ROWS       96
63	#define NUM_CHANNELS   1
64	#define CATEGORY_COUNT 2
65	#define PERSON_INDEX   1
66	#define NOT_PERSON_IDX 0
67	
68	/* Tensor arena size - must be large enough for the model */
69	
70	#define TENSOR_ARENA_SIZE (136 * 1024)
71	
72	/* BMP file header size for 96x96 grayscale */
73	
74	#define BMP_HEADER_SIZE  1078  /* 14 file header + 40 DIB header + 256 palette */
75	
76	/****************************************************************************
77	 * Private Data
78	 ****************************************************************************/
79	
80	static const char *g_category_labels[CATEGORY_COUNT] =
81	{
82	  "notperson",
83	  "person"
84	};
85	
86	/* Tensor arena - aligned to 16 bytes for SIMD optimization */
87	
88	static uint8_t g_tensor_arena[TENSOR_ARENA_SIZE] __attribute__((aligned(16)));
89	
90	/****************************************************************************
91	 * Private Functions
92	 ****************************************************************************/
93	
94	/****************************************************************************
95	 * Name: load_bmp_grayscale
96	 *
97	 * Description:
98	 *   Load a 96x96 grayscale BMP file and convert to INT8 format expected by
99	 *   the model (signed int8, where 0 = -128, 255 = 127).
100	 *
101	 * Input Parameters:
102	 *   filepath   - Path to the BMP file
103	 *   image_data - Output buffer (must be at least 96*96 bytes)
104	 *
105	 * Returned Value:
106	 *   0 on success, negative errno on failure
107	 *
108	 ****************************************************************************/
109	
110	static int load_bmp_grayscale(const char *filepath, int8_t *image_data)
111	{
112	  uint8_t header[BMP_HEADER_SIZE];
113	  uint8_t pixel;
114	  int fd;
115	  int ret = 0;
116	  int i;
117	
118	  fd = open(filepath, O_RDONLY);
119	  if (fd < 0)
120	    {
121	      fprintf(stderr, "ERROR: Failed to open %s: %d\n", filepath, errno);
122	      return -errno;
123	    }
124	
125	  /* Read BMP header */
126	
127	  if (read(fd, header, BMP_HEADER_SIZE) != BMP_HEADER_SIZE)
128	    {
129	      fprintf(stderr, "ERROR: Failed to read BMP header\n");
130	      ret = -EIO;
131	      goto errout;
132	    }
133	
134	  /* Verify BMP magic number */
135	
136	  if (header[0] != 'B' || header[1] != 'M')
137	    {
138	      fprintf(stderr, "ERROR: Not a valid BMP file\n");
139	      ret = -EINVAL;
140	      goto errout;
141	    }
142	
143	  /* Read pixel data and convert unsigned [0,255] to signed [-128,127] */
144	
145	  for (i = 0; i < NUM_ROWS * NUM_COLS; i++)
146	    {
147	      if (read(fd, &pixel, 1) != 1)
148	        {
149	          fprintf(stderr, "ERROR: Failed to read pixel data at offset %d\n",
150	                  i);
151	          ret = -EIO;
152	          goto errout;
153	        }
154	
155	      /* BMP stores bottom-to-top, flip vertically */
156	
157	      int row = i / NUM_COLS;
158	      int col = i % NUM_COLS;
159	      int flipped_row = NUM_ROWS - 1 - row;
160	      int idx = flipped_row * NUM_COLS + col;
161	
162	      /* Convert unsigned [0,255] to signed int8 [-128,127] */
163	
164	      image_data[idx] = static_cast<int8_t>(static_cast<int>(pixel) - 128);
165	    }
166	
167	errout:
168	  close(fd);
169	  return ret;
170	}
