185	/****************************************************************************
186	 * Public Functions
187	 ****************************************************************************/
188	
189	/****************************************************************************
190	 * main
191	 ****************************************************************************/
192	
193	extern "C" int main(int argc, char *argv[])
194	{
195	  const tflite::Model *model = nullptr;
196	  tflite::MicroInterpreter *interpreter = nullptr;
197	  TfLiteTensor *input = nullptr;
198	  TfLiteTensor *output = nullptr;
199	  const char *image_path = nullptr;
200	  int iterations = 1;
201	  int opt;
202	  int ret = 0;
203	
204	  /* Parse command line arguments */
205	
206	  while ((opt = getopt(argc, argv, "t:r:h")) != -1)
207	    {
208	      switch (opt)
209	        {
210	          case 't':
211	            image_path = optarg;
212	            break;
213	          case 'r':
214	            iterations = atoi(optarg);
215	            if (iterations <= 0)
216	              {
217	                iterations = 1;
218	              }
219	            break;
220	          case 'h':
221	          default:
222	            print_usage(argv[0]);
223	            return (opt == 'h') ? 0 : 1;
224	        }
225	    }
226	
227	  tflite::InitializeTarget();
228	
229	  printf("=== Person Detection Demo ===\n");
230	  printf("Model size: %u bytes\n", g_person_detect_model_data_len);
231	  fflush(stdout);
232	
233	  /* Map the model into a usable data structure.
234	   * This doesn't involve any copying or parsing.
235	   */
236	
237	  model = tflite::GetModel(g_person_detect_model_data);
238	  if (model->version() != TFLITE_SCHEMA_VERSION)
239	    {
240	      fprintf(stderr, "ERROR: Model schema version %d != supported %d\n",
241	              model->version(), TFLITE_SCHEMA_VERSION);
242	      return 1;
243	    }
244	
245	  printf("Model version OK\n");
246	  fflush(stdout);
247	
248	  /* Register only the operations we need.
249	   * person_detect model uses: Conv2D, DepthwiseConv2D, AveragePool2D,
250	   * Reshape, Softmax (all INT8 quantized).
251	   */
252	
253	  tflite::MicroMutableOpResolver<5> op_resolver;
254	  op_resolver.AddConv2D(tflite::Register_CONV_2D_INT8());
255	  op_resolver.AddDepthwiseConv2D(tflite::Register_DEPTHWISE_CONV_2D_INT8());
256	  op_resolver.AddAveragePool2D(tflite::Register_AVERAGE_POOL_2D_INT8());
257	  op_resolver.AddReshape();
258	  op_resolver.AddSoftmax(tflite::Register_SOFTMAX_INT8());
259	
260	  printf("Op resolver OK\n");
261	  fflush(stdout);
262	
263	  /* Build an interpreter to run the model */
264	
265	  tflite::MicroInterpreter micro_interpreter(
266	      model, op_resolver, g_tensor_arena, TENSOR_ARENA_SIZE);
267	  interpreter = &micro_interpreter;
268	
269	  printf("Interpreter created, allocating tensors...\n");
270	  fflush(stdout);
271	
272	  /* Allocate memory from the tensor_arena for the model's tensors */
273	
274	  TfLiteStatus allocate_status = interpreter->AllocateTensors();
275	  if (allocate_status != kTfLiteOk)
276	    {
277	      fprintf(stderr, "ERROR: AllocateTensors() failed\n");
278	      fflush(stderr);
279	      return 1;
280	    }
281	
282	  printf("Tensors allocated OK\n");
283	  fflush(stdout);
284	
285	  /* Get input and output tensor pointers */
286	
287	  input = interpreter->input(0);
288	  output = interpreter->output(0);
289	
290	  printf("Input tensor: %dx%dx%d (type: INT8)\n",
291	         input->dims->data[1], input->dims->data[2], input->dims->data[3]);
292	  printf("Output tensor: %d categories\n",
293	         output->dims->data[1]);
294	  printf("Tensor arena used: %zu / %d bytes\n",
295	         interpreter->arena_used_bytes(), TENSOR_ARENA_SIZE);
296	  printf("\n");
297	
298	  /* Run inference */
299	
300	  for (int iter = 0; iter < iterations; iter++)
301	    {
302	      if (iterations > 1)
303	        {
304	          printf("--- Iteration %d/%d ---\n", iter + 1, iterations);
305	        }
306	
307	      /* Load image data */
308	
309	      if (image_path != nullptr)
310	        {
311	          printf("Loading image: %s\n", image_path);
312	          fflush(stdout);
313	          ret = load_bmp_grayscale(image_path, input->data.int8);
314	          if (ret < 0)
315	            {
316	              fprintf(stderr, "ERROR: Failed to load image\n");
317	              return 1;
318	            }
319	        }
320	      else
321	        {
322	          /* Use a blank (zero) image - just for testing the pipeline */
323	
324	          printf("Using blank image (all zeros)\n");
325	          memset(input->data.int8, 0, NUM_ROWS * NUM_COLS * NUM_CHANNELS);
326	        }
327	
328	      fflush(stdout);
329	
330	      /* Run the model */
331	
332	      printf("Running inference...\n");
