/****************************************************************************
 * Person Detection Demo for openvela/NuttX
 *
 * This application uses TFLite Micro to run a MobileNet V1 based person
 * detection model (INT8 quantized, 96x96 grayscale input).
 *
 * Usage:
 *   person_detection              - Run with a blank (zero) image
 *   person_detection -t <file>    - Run with test BMP image
 *   person_detection -c           - Capture from camera and detect
 *   person_detection -c -r <N>    - Camera mode, run N frames
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cerrno>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#include <nuttx/video/video.h>
#include <nuttx/video/v4l2_cap.h>

#include "tensorflow/lite/micro/micro_interpreter.h"
#include "tensorflow/lite/micro/micro_log.h"
#include "tensorflow/lite/micro/micro_mutable_op_resolver.h"
#include "tensorflow/lite/micro/system_setup.h"
#include "tensorflow/lite/schema/schema_generated.h"

/* Model data embedded directly as static arrays */

#include "person_detect_model_data.inc"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Model input parameters (from person_detect model training) */

#define NUM_COLS       96
#define NUM_ROWS       96
#define NUM_CHANNELS   1
#define CATEGORY_COUNT 2
#define PERSON_INDEX   1
#define NOT_PERSON_IDX 0

/* Tensor arena size - must be large enough for the model */

#define TENSOR_ARENA_SIZE (136 * 1024)

/* BMP file header size for 96x96 grayscale */

#define BMP_HEADER_SIZE  1078  /* 14 file header + 40 DIB header + 256 palette */

/* Camera capture parameters */

#define CAM_DEV_PATH   "/dev/video"
#define CAM_WIDTH      320
#define CAM_HEIGHT     240
#define CAM_BUF_COUNT  4

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct cam_buffer_s
{
  uint8_t *start;
  uint32_t length;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const char *g_category_labels[CATEGORY_COUNT] =
{
  "notperson",
  "person"
};

/* Tensor arena - aligned to 16 bytes for SIMD optimization */

static uint8_t g_tensor_arena[TENSOR_ARENA_SIZE] __attribute__((aligned(16)));

/****************************************************************************
 * MJPEG decode via tjpgd (from uvc_test)
 ****************************************************************************/

#include "tjpgd.h"

struct mjpeg_iodev_s
{
  const uint8_t *data;
  size_t         len;
  size_t         pos;
};

/* Decoded grayscale buffer: 96x96, used by mjpeg_output callback */

static int8_t *g_decode_target = nullptr;

static size_t mjpeg_input(JDEC *jd, uint8_t *buff, size_t nbyte)
{
  struct mjpeg_iodev_s *io = (struct mjpeg_iodev_s *)jd->device;
  size_t avail = io->len - io->pos;

  if (nbyte > avail)
    {
      nbyte = avail;
    }

  if (buff)
    {
      memcpy(buff, io->data + io->pos, nbyte);
    }

  io->pos += nbyte;
  return nbyte;
}

/****************************************************************************
 * Name: mjpeg_output
 *
 * Description:
 *   tjpgd output callback.  Decoded RGB blocks are downsampled to 96x96
 *   grayscale and written directly into g_decode_target (INT8 format).
 *
 ****************************************************************************/

static int mjpeg_output(JDEC *jd, void *bitmap, JRECT *rect)
{
  uint8_t *src = (uint8_t *)bitmap;
  uint32_t src_w = jd->width;
  uint32_t src_h = jd->height;

  /* Map each pixel in this decoded block to the corresponding 96x96 cell */

  for (uint32_t y = rect->top; y <= rect->bottom; y++)
    {
      for (uint32_t x = rect->left; x <= rect->right; x++)
        {
          uint8_t b = *src++;
          uint8_t g = *src++;
          uint8_t r = *src++;

          /* Map to 96x96 grid */

          int dx = (int)(x * NUM_COLS / src_w);
          int dy = (int)(y * NUM_ROWS / src_h);

          if (dx >= NUM_COLS)
            {
              dx = NUM_COLS - 1;
            }

          if (dy >= NUM_ROWS)
            {
              dy = NUM_ROWS - 1;
            }

          /* RGB to grayscale: 0.299R + 0.587G + 0.114B */

          int gray = (77 * r + 150 * g + 29 * b) >> 8;

          /* Convert unsigned [0,255] to signed int8 [-128,127] */

          g_decode_target[dy * NUM_COLS + dx] =
              static_cast<int8_t>(gray - 128);
        }
    }

  return 1;
}

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: load_bmp_grayscale
 *
 * Description:
 *   Load a 96x96 grayscale BMP file and convert to INT8 format.
 *
 ****************************************************************************/

static int load_bmp_grayscale(const char *filepath, int8_t *image_data)
{
  uint8_t header[BMP_HEADER_SIZE];
  uint8_t pixel;
  int fd;
  int ret = 0;
  int i;

  fd = open(filepath, O_RDONLY);
  if (fd < 0)
    {
      fprintf(stderr, "ERROR: Failed to open %s: %d\n", filepath, errno);
      return -errno;
    }

  if (read(fd, header, BMP_HEADER_SIZE) != BMP_HEADER_SIZE)
    {
      fprintf(stderr, "ERROR: Failed to read BMP header\n");
      ret = -EIO;
      goto errout;
    }

  if (header[0] != 'B' || header[1] != 'M')
    {
      fprintf(stderr, "ERROR: Not a valid BMP file\n");
      ret = -EINVAL;
      goto errout;
    }

  for (i = 0; i < NUM_ROWS * NUM_COLS; i++)
    {
      if (read(fd, &pixel, 1) != 1)
        {
          fprintf(stderr, "ERROR: Failed to read pixel data at offset %d\n",
                  i);
          ret = -EIO;
          goto errout;
        }

      /* BMP stores bottom-to-top, flip vertically */

      int row = i / NUM_COLS;
      int col = i % NUM_COLS;
      int flipped_row = NUM_ROWS - 1 - row;
      int idx = flipped_row * NUM_COLS + col;

      image_data[idx] = static_cast<int8_t>(static_cast<int>(pixel) - 128);
    }

errout:
  close(fd);
  return ret;
}

/****************************************************************************
 * Name: capture_camera_frame
 *
 * Description:
 *   Open UVC camera, capture one MJPEG frame, decode to 96x96 grayscale
 *   INT8 via tjpgd, then close the camera.
 *
 ****************************************************************************/

static int capture_camera_frame(int8_t *image_data)
{
  struct v4l2_format fmt;
  struct v4l2_requestbuffers req;
  struct v4l2_buffer buf;
  struct cam_buffer_s *buffers = nullptr;
  enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  int fd = -1;
  int ret;
  int i;
  int captured = 0;

  printf("Opening camera: %s\n", CAM_DEV_PATH);
  fflush(stdout);

  /* Initialize video driver */

  ret = capture_initialize(CAM_DEV_PATH);
  if (ret != 0)
    {
      fprintf(stderr, "ERROR: capture_initialize failed: %d\n", ret);
      return -EIO;
    }

  fd = open(CAM_DEV_PATH, O_RDWR);
  if (fd < 0)
    {
      fprintf(stderr, "ERROR: Failed to open %s: %d\n", CAM_DEV_PATH, errno);
      capture_uninitialize(CAM_DEV_PATH);
      return -errno;
    }

  /* Set MJPEG format */

  memset(&fmt, 0, sizeof(fmt));
  fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  fmt.fmt.pix.width = CAM_WIDTH;
  fmt.fmt.pix.height = CAM_HEIGHT;
  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
  fmt.fmt.pix.field = V4L2_FIELD_NONE;

  ret = ioctl(fd, VIDIOC_S_FMT, (uintptr_t)&fmt);
  if (ret < 0)
    {
      fprintf(stderr, "ERROR: VIDIOC_S_FMT failed: %d\n", errno);
      goto errout;
    }

  if (fmt.fmt.pix.sizeimage == 0)
    {
      fmt.fmt.pix.sizeimage = CAM_WIDTH * CAM_HEIGHT * 2;
    }

  printf("Camera format: %ux%u MJPEG, buf size: %u\n",
         fmt.fmt.pix.width, fmt.fmt.pix.height, fmt.fmt.pix.sizeimage);
  fflush(stdout);

  /* Request buffers */

  memset(&req, 0, sizeof(req));
  req.count = CAM_BUF_COUNT;
  req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  req.memory = V4L2_MEMORY_USERPTR;

  ret = ioctl(fd, VIDIOC_REQBUFS, (uintptr_t)&req);
  if (ret < 0)
    {
      fprintf(stderr, "ERROR: VIDIOC_REQBUFS failed: %d\n", errno);
      goto errout;
    }

  buffers = (struct cam_buffer_s *)malloc(req.count * sizeof(struct cam_buffer_s));
  if (buffers == nullptr)
    {
      fprintf(stderr, "ERROR: Failed to allocate buffer array\n");
      ret = -ENOMEM;
      goto errout;
    }

  for (i = 0; i < (int)req.count; i++)
    {
      buffers[i].length = fmt.fmt.pix.sizeimage;
      buffers[i].start = (uint8_t *)memalign(64, buffers[i].length);
      if (buffers[i].start == nullptr)
        {
          fprintf(stderr, "ERROR: Failed to allocate buffer %d\n", i);
          ret = -ENOMEM;
          goto err_free;
        }

      memset(&buf, 0, sizeof(buf));
      buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      buf.memory = V4L2_MEMORY_USERPTR;
      buf.index = i;
      buf.m.userptr = (uintptr_t)buffers[i].start;
      buf.length = buffers[i].length;

      ret = ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);
      if (ret < 0)
        {
          fprintf(stderr, "ERROR: VIDIOC_QBUF failed: %d\n", errno);
          goto err_free;
        }
    }

  /* Start streaming */

  ret = ioctl(fd, VIDIOC_STREAMON, (uintptr_t)&type);
  if (ret < 0)
    {
      fprintf(stderr, "ERROR: VIDIOC_STREAMON failed: %d\n", errno);
      goto err_free;
    }

  printf("Camera streaming, capturing frame...\n");
  fflush(stdout);

  /* Dequeue one frame */

  memset(&buf, 0, sizeof(buf));
  buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  buf.memory = V4L2_MEMORY_USERPTR;

  ret = ioctl(fd, VIDIOC_DQBUF, (uintptr_t)&buf);
  if (ret < 0)
    {
      fprintf(stderr, "ERROR: VIDIOC_DQBUF failed: %d\n", errno);
      goto err_streamoff;
    }

  /* Decode MJPEG to grayscale 96x96 using tjpgd */

  printf("Decoding JPEG (%u bytes)...\n", buf.bytesused);
  fflush(stdout);

  {
    static uint8_t jdwork[4096];
    JDEC jdec;
    struct mjpeg_iodev_s iodev;

    iodev.data = (const uint8_t *)buf.m.userptr;
    iodev.len  = buf.bytesused;
    iodev.pos  = 0;

    g_decode_target = image_data;
    memset(image_data, 0, NUM_ROWS * NUM_COLS);

    ret = jd_prepare(&jdec, mjpeg_input, jdwork, sizeof(jdwork), &iodev);
    if (ret != JDR_OK)
      {
        fprintf(stderr, "ERROR: jd_prepare failed: %d\n", ret);
        goto err_streamoff;
      }

    /* Reset input position for decompression */

    iodev.pos = 0;

    ret = jd_decomp(&jdec, mjpeg_output, 0);
    if (ret != JDR_OK)
      {
        fprintf(stderr, "ERROR: jd_decomp failed: %d\n", ret);
        goto err_streamoff;
      }

    printf("Decoded %ux%u -> %dx%d grayscale\n",
           jdec.width, jdec.height, NUM_COLS, NUM_ROWS);
    captured = 1;
  }

  /* Requeue the buffer */

  ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);

err_streamoff:
  ioctl(fd, VIDIOC_STREAMOFF, (uintptr_t)&type);

err_free:
  if (buffers)
    {
      for (i = 0; i < (int)req.count; i++)
        {
          if (buffers[i].start)
            {
              free(buffers[i].start);
            }
        }

      free(buffers);
    }

errout:
  if (fd >= 0)
    {
      close(fd);
    }

  capture_uninitialize(CAM_DEV_PATH);

  return captured ? 0 : -EIO;
}

/****************************************************************************
 * Name: print_usage
 ****************************************************************************/

static void print_usage(const char *progname)
{
  printf("Usage: %s [options]\n", progname);
  printf("  -c         Capture from camera and detect\n");
  printf("  -t <file>  Load test image from BMP file\n");
  printf("  -r <N>     Run N iterations (for benchmarking)\n");
  printf("  -h         Show this help\n");
  printf("\nWithout options, runs once with a blank (zero) image.\n");
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * main
 ****************************************************************************/

extern "C" int main(int argc, char *argv[])
{
  const tflite::Model *model = nullptr;
  tflite::MicroInterpreter *interpreter = nullptr;
  TfLiteTensor *input = nullptr;
  TfLiteTensor *output = nullptr;
  const char *image_path = nullptr;
  int iterations = 1;
  int use_camera = 0;
  int opt;
  int ret = 0;

  /* Parse command line arguments */

  while ((opt = getopt(argc, argv, "ct:r:h")) != -1)
    {
      switch (opt)
        {
          case 'c':
            use_camera = 1;
            break;
          case 't':
            image_path = optarg;
            break;
          case 'r':
            iterations = atoi(optarg);
            if (iterations <= 0)
              {
                iterations = 1;
              }
            break;
          case 'h':
          default:
            print_usage(argv[0]);
            return (opt == 'h') ? 0 : 1;
        }
    }

  tflite::InitializeTarget();

  printf("=== Person Detection Demo ===\n");
  printf("Model size: %u bytes\n", g_person_detect_model_data_len);
  fflush(stdout);

  model = tflite::GetModel(g_person_detect_model_data);
  if (model->version() != TFLITE_SCHEMA_VERSION)
    {
      fprintf(stderr, "ERROR: Model schema version %d != supported %d\n",
              model->version(), TFLITE_SCHEMA_VERSION);
      return 1;
    }

  printf("Model version OK\n");
  fflush(stdout);

  tflite::MicroMutableOpResolver<5> op_resolver;
  op_resolver.AddConv2D(tflite::Register_CONV_2D_INT8());
  op_resolver.AddDepthwiseConv2D(tflite::Register_DEPTHWISE_CONV_2D_INT8());
  op_resolver.AddAveragePool2D(tflite::Register_AVERAGE_POOL_2D_INT8());
  op_resolver.AddReshape();
  op_resolver.AddSoftmax(tflite::Register_SOFTMAX_INT8());

  printf("Op resolver OK\n");
  fflush(stdout);

  tflite::MicroInterpreter micro_interpreter(
      model, op_resolver, g_tensor_arena, TENSOR_ARENA_SIZE);
  interpreter = &micro_interpreter;

  printf("Interpreter created, allocating tensors...\n");
  fflush(stdout);

  TfLiteStatus allocate_status = interpreter->AllocateTensors();
  if (allocate_status != kTfLiteOk)
    {
      fprintf(stderr, "ERROR: AllocateTensors() failed\n");
      fflush(stderr);
      return 1;
    }

  printf("Tensors allocated OK\n");

  input = interpreter->input(0);
  output = interpreter->output(0);

  printf("Input tensor: %dx%dx%d (type: INT8)\n",
         input->dims->data[1], input->dims->data[2], input->dims->data[3]);
  printf("Output tensor: %d categories\n",
         output->dims->data[1]);
  printf("Tensor arena used: %zu / %d bytes\n",
         interpreter->arena_used_bytes(), TENSOR_ARENA_SIZE);
  printf("\n");
  fflush(stdout);

  /* Run inference */

  for (int iter = 0; iter < iterations; iter++)
    {
      if (iterations > 1)
        {
          printf("--- Iteration %d/%d ---\n", iter + 1, iterations);
          fflush(stdout);
        }

      /* Load image data */

      if (use_camera)
        {
          printf("Capturing from camera...\n");
          fflush(stdout);
          ret = capture_camera_frame(input->data.int8);
          if (ret < 0)
            {
              fprintf(stderr, "ERROR: Camera capture failed\n");
              return 1;
            }
        }
      else if (image_path != nullptr)
        {
          printf("Loading image: %s\n", image_path);
          fflush(stdout);
          ret = load_bmp_grayscale(image_path, input->data.int8);
          if (ret < 0)
            {
              fprintf(stderr, "ERROR: Failed to load image\n");
              return 1;
            }
        }
      else
        {
          printf("Using blank image (all zeros)\n");
          memset(input->data.int8, 0, NUM_ROWS * NUM_COLS * NUM_CHANNELS);
        }

      fflush(stdout);

      /* Run the model */

      printf("Running inference...\n");
      fflush(stdout);
      TfLiteStatus invoke_status = interpreter->Invoke();
      if (invoke_status != kTfLiteOk)
        {
          fprintf(stderr, "ERROR: Invoke() failed\n");
          return 1;
        }

      /* Process the output */

      int8_t person_score = output->data.int8[PERSON_INDEX];
      int8_t no_person_score = output->data.int8[NOT_PERSON_IDX];

      printf("Result:\n");
      printf("  %-12s score: %d\n", g_category_labels[NOT_PERSON_IDX],
             no_person_score);
      printf("  %-12s score: %d\n", g_category_labels[PERSON_INDEX],
             person_score);

      if (person_score > no_person_score)
        {
          printf("  >>> PERSON DETECTED <<<\n");
        }
      else
        {
          printf("  >>> No person detected <<<\n");
        }

      printf("\n");
      fflush(stdout);
    }

  printf("Done.\n");
  return 0;
}

