/****************************************************************************
 * Private Data
 ****************************************************************************/

static const char *g_category_labels[CATEGORY_COUNT] =
{
  "notperson",
  "person"
};

static uint8_t g_tensor_arena[TENSOR_ARENA_SIZE] __attribute__((aligned(16)));

/* Display buffers */

static uint16_t g_rgbbuf[CAM_WIDTH * CAM_HEIGHT];
static struct fb_videoinfo_s g_vinfo;
static int g_fbfd = -1;

/* Grayscale buffer for inference */

static int8_t g_graybuf[NUM_ROWS * NUM_COLS];

/****************************************************************************
 * Inline Helpers
 ****************************************************************************/

static inline uint8_t clamp8(int v)
{
  if (v < 0) return 0;
  if (v > 255) return 255;
  return (uint8_t)v;
}

static inline uint16_t rgb565(uint8_t r, uint8_t g, uint8_t b)
{
  return ((r & 0xf8) << 8) | ((g & 0xfc) << 3) | (b >> 3);
}

/****************************************************************************
 * tjpgd Callbacks
 ****************************************************************************/

static size_t mjpeg_input(JDEC *jd, uint8_t *buff, size_t nbyte)
{
  struct mjpeg_iodev_s *io = (struct mjpeg_iodev_s *)jd->device;
  size_t avail = io->len - io->pos;
  if (nbyte > avail) nbyte = avail;
  if (buff) memcpy(buff, io->data + io->pos, nbyte);
  io->pos += nbyte;
  return nbyte;
}

/* Output callback: decode to RGB565 display buffer AND 96x96 grayscale */

static int mjpeg_output(JDEC *jd, void *bitmap, JRECT *rect)
{
  struct decode_ctx_s *ctx = (struct decode_ctx_s *)jd->device;
  uint8_t *src = (uint8_t *)bitmap;
  uint32_t src_w = ctx->src_w;
  uint32_t src_h = ctx->src_h;

  for (uint32_t y = rect->top; y <= rect->bottom; y++)
    {
      for (uint32_t x = rect->left; x <= rect->right; x++)
        {
          uint8_t b = *src++;
          uint8_t g = *src++;
          uint8_t r = *src++;

          /* Write to RGB565 display buffer */

          if (x < CAM_WIDTH && y < CAM_HEIGHT)
            {
              ctx->rgb565[y * CAM_WIDTH + x] = rgb565(r, g, b);
            }

          /* Downsample to 96x96 grayscale */

          if (ctx->grayscale)
            {
              int dx = (int)((uint32_t)x * NUM_COLS / src_w);
              int dy = (int)((uint32_t)y * NUM_ROWS / src_h);
              if (dx >= NUM_COLS) dx = NUM_COLS - 1;
              if (dy >= NUM_ROWS) dy = NUM_ROWS - 1;

              int gray = (77 * r + 150 * g + 29 * b) >> 8;
              ctx->grayscale[dy * NUM_COLS + dx] =
                  static_cast<int8_t>(gray - 128);
            }
        }
    }

  return 1;
}

/****************************************************************************
 * Framebuffer / LCD Functions
 ****************************************************************************/

static int fb_open(void)
{
  int ret;

  g_fbfd = open(FB_DEV_PATH, O_RDWR);
  if (g_fbfd < 0)
    {
      fprintf(stderr, "ERROR: open %s failed: %d\n", FB_DEV_PATH, errno);
      return -errno;
    }

  ret = ioctl(g_fbfd, LCDDEVIO_GETVIDEOINFO, (uintptr_t)&g_vinfo);
  if (ret < 0)
    {
      fprintf(stderr, "ERROR: LCDDEVIO_GETVIDEOINFO failed: %d\n", errno);
      close(g_fbfd);
      g_fbfd = -1;
      return -errno;
    }

  printf("LCD: %ux%u fmt=%u\n", g_vinfo.xres, g_vinfo.yres, g_vinfo.fmt);
  return OK;
}

static void fb_blit(uint32_t w, uint32_t h)
{
  struct lcddev_area_s area;
  memset(&area, 0, sizeof(area));
  area.row_start = 0;
  area.row_end   = h - 1;
  area.col_start = 0;
  area.col_end   = w - 1;
  area.stride    = w * 2;
  area.data      = (FAR uint8_t *)g_rgbbuf;
  ioctl(g_fbfd, LCDDEVIO_PUTAREA, (uintptr_t)&area);
}

/****************************************************************************
 * Overlay Drawing Functions
 ****************************************************************************/

static void draw_pixel(int x, int y, uint16_t color)
{
  if (x >= 0 && x < (int)CAM_WIDTH && y >= 0 && y < (int)CAM_HEIGHT)
    {
      g_rgbbuf[y * CAM_WIDTH + x] = color;
    }
}

static void draw_rect(int x0, int y0, int x1, int y1, uint16_t color)
{
  for (int x = x0; x <= x1; x++)
    {
      draw_pixel(x, y0, color);
      draw_pixel(x, y1, color);
    }

  for (int y = y0; y <= y1; y++)
    {
      draw_pixel(x0, y, color);
      draw_pixel(x1, y, color);
    }
}

static void draw_filled_rect(int x0, int y0, int x1, int y1,
                              uint16_t color)
{
  for (int y = y0; y <= y1; y++)
    {
      for (int x = x0; x <= x1; x++)
        {
          draw_pixel(x, y, color);
        }
    }
}

static void draw_char(int x, int y, char c, uint16_t color, int scale)
{
  if (c < 32 || c > 90) return;  /* Only support ASCII 32-90 */
  int idx = c - 32;
  if (idx < 0 || idx >= (int)(sizeof(g_font5x7) / FONT_W)) return;

  const uint8_t *glyph = g_font5x7[idx];
  for (int col = 0; col < FONT_W; col++)
    {
      uint8_t line = glyph[col];
      for (int row = 0; row < FONT_H; row++)
        {
          if (line & (1 << row))
            {
              for (int sy = 0; sy < scale; sy++)
                {
                  for (int sx = 0; sx < scale; sx++)
                    {
                      draw_pixel(x + col * scale + sx,
                                 y + row * scale + sy, color);
                    }
                }
            }
        }
    }
}

static void draw_string(int x, int y, const char *str,
                         uint16_t color, int scale)
{
  while (*str)
    {
      draw_char(x, y, *str, color, scale);
      x += (FONT_W + 1) * scale;
      str++;
    }
}

static void draw_number(int x, int y, int num, uint16_t color, int scale)
{
  char buf[12];
  snprintf(buf, sizeof(buf), "%d", num);
  draw_string(x, y, buf, color, scale);
}

/****************************************************************************
 * Name: overlay_result
 *
 * Description:
 *   Draw detection result overlay on the RGB565 display buffer.
 *
 ****************************************************************************/

static void overlay_result(int8_t person_score, int8_t no_person_score,
                           int detected)
{
  uint16_t bg_color;
  uint16_t text_color;
  const char *label;

  if (detected)
    {
      bg_color   = rgb565(0, 128, 0);   /* green background */
      text_color = 0xFFFF;               /* white text */
      label      = "PERSON";
    }
  else
    {
      bg_color   = rgb565(128, 0, 0);   /* red background */
      text_color = 0xFFFF;               /* white text */
      label      = "NO PERSON";
    }

  /* Draw background bar at top */

  draw_filled_rect(0, 0, CAM_WIDTH - 1, (FONT_H + 4) * FONT_SCALE,
                    bg_color);

  /* Draw label */

  draw_string(4, 2, label, text_color, FONT_SCALE);

  /* Draw scores */

  char score_str[32];
  snprintf(score_str, sizeof(score_str), "P:%d N:%d",
           person_score, no_person_score);
  draw_string(CAM_WIDTH - (FONT_W + 1) * FONT_SCALE * 12, 2,
              score_str, text_color, FONT_SCALE);
}

/****************************************************************************
 * BMP Loader
 ****************************************************************************/

static int load_bmp_grayscale(const char *filepath, int8_t *image_data)
{
  uint8_t header[BMP_HEADER_SIZE];
  uint8_t pixel;
  int fd;
  int ret = 0;
  int i;

  fd = open(filepath, O_RDONLY);
  if (fd < 0)
    {
      fprintf(stderr, "ERROR: Failed to open %s: %d\n", filepath, errno);
      return -errno;
    }

  if (read(fd, header, BMP_HEADER_SIZE) != BMP_HEADER_SIZE)
    {
      fprintf(stderr, "ERROR: Failed to read BMP header\n");
      ret = -EIO;
      goto errout;
    }

  if (header[0] != 'B' || header[1] != 'M')
    {
      fprintf(stderr, "ERROR: Not a valid BMP file\n");
      ret = -EINVAL;
      goto errout;
    }

  for (i = 0; i < NUM_ROWS * NUM_COLS; i++)
    {
      if (read(fd, &pixel, 1) != 1)
        {
          fprintf(stderr, "ERROR: Failed to read pixel at offset %d\n", i);
          ret = -EIO;
          goto errout;
        }

      int row = i / NUM_COLS;
      int col = i % NUM_COLS;
      int flipped_row = NUM_ROWS - 1 - row;
      int idx = flipped_row * NUM_COLS + col;
      image_data[idx] = static_cast<int8_t>(static_cast<int>(pixel) - 128);
    }

errout:
  close(fd);
  return ret;
}

/****************************************************************************
 * Camera Capture
 ****************************************************************************/

static int capture_and_decode(int8_t *gray_out, uint16_t *rgb_out,
                               uint32_t *out_w, uint32_t *out_h)
{
  struct v4l2_format fmt;
  struct v4l2_requestbuffers req;
  struct v4l2_buffer buf;
  struct cam_buffer_s *buffers = nullptr;
  enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  int fd = -1;
  int ret;
  int i;
  int ok = 0;

  ret = capture_initialize(CAM_DEV_PATH);
  if (ret != 0)
    {
      fprintf(stderr, "ERROR: capture_initialize failed: %d\n", ret);
      return -EIO;
    }

  fd = open(CAM_DEV_PATH, O_RDWR);
  if (fd < 0)
    {
      fprintf(stderr, "ERROR: open %s failed: %d\n", CAM_DEV_PATH, errno);
      capture_uninitialize(CAM_DEV_PATH);
      return -errno;
    }

  memset(&fmt, 0, sizeof(fmt));
  fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  fmt.fmt.pix.width = CAM_WIDTH;
  fmt.fmt.pix.height = CAM_HEIGHT;
  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
  fmt.fmt.pix.field = V4L2_FIELD_NONE;

  ret = ioctl(fd, VIDIOC_S_FMT, (uintptr_t)&fmt);
  if (ret < 0)
    {
      fprintf(stderr, "ERROR: VIDIOC_S_FMT failed: %d\n", errno);
      goto errout;
    }

  if (fmt.fmt.pix.sizeimage == 0)
    {
      fmt.fmt.pix.sizeimage = CAM_WIDTH * CAM_HEIGHT * 2;
    }

  memset(&req, 0, sizeof(req));
  req.count = CAM_BUF_COUNT;
  req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  req.memory = V4L2_MEMORY_USERPTR;

  ret = ioctl(fd, VIDIOC_REQBUFS, (uintptr_t)&req);
  if (ret < 0)
    {
      fprintf(stderr, "ERROR: VIDIOC_REQBUFS failed: %d\n", errno);
      goto errout;
    }

  buffers = (struct cam_buffer_s *)malloc(req.count * sizeof(struct cam_buffer_s));
  if (!buffers)
    {
      ret = -ENOMEM;
      goto errout;
    }

  for (i = 0; i < (int)req.count; i++)
    {
      buffers[i].length = fmt.fmt.pix.sizeimage;
      buffers[i].start = (uint8_t *)memalign(64, buffers[i].length);
      if (!buffers[i].start)
        {
          goto err_free;
        }

      memset(&buf, 0, sizeof(buf));
      buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      buf.memory = V4L2_MEMORY_USERPTR;
      buf.index = i;
      buf.m.userptr = (uintptr_t)buffers[i].start;
      buf.length = buffers[i].length;

      ret = ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);
      if (ret < 0)
        {
          goto err_free;
        }
    }

  ret = ioctl(fd, VIDIOC_STREAMON, (uintptr_t)&type);
  if (ret < 0)
    {
      fprintf(stderr, "ERROR: VIDIOC_STREAMON failed: %d\n", errno);
      goto err_free;
    }

  /* Grab one frame */

  memset(&buf, 0, sizeof(buf));
  buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  buf.memory = V4L2_MEMORY_USERPTR;

  ret = ioctl(fd, VIDIOC_DQBUF, (uintptr_t)&buf);
  if (ret < 0)
    {
      fprintf(stderr, "ERROR: VIDIOC_DQBUF failed: %d\n", errno);
      goto err_streamoff;
    }

  /* Decode JPEG → RGB565 + grayscale */

  {
    static uint8_t jdwork[4096];
    JDEC jdec;
    struct mjpeg_iodev_s iodev;
    struct decode_ctx_s dctx;

    iodev.data = (const uint8_t *)buf.m.userptr;
    iodev.len  = buf.bytesused;
    iodev.pos  = 0;

    dctx.rgb565    = rgb_out;
    dctx.grayscale = gray_out;
    dctx.src_w     = CAM_WIDTH;
    dctx.src_h     = CAM_HEIGHT;

    /* jd_prepare uses jd->device for the user pointer, but we need
     * to pass our decode context through it.  We store the iodev in
     * jd->device for prepare, then swap to dctx for decomp.
     */

    ret = jd_prepare(&jdec, mjpeg_input, jdwork, sizeof(jdwork), &iodev);
    if (ret == JDR_OK)
      {
        iodev.pos = 0;

        /* Hack: tjpgd passes jd->device to the output callback.
         * We set jd->device to our decode context so mjpeg_output
         * can access both rgb565 and grayscale buffers.
         * For the input callback, we need iodev.  We solve this by
         * making mjpeg_input use a global (g_mjpeg_io) instead.
         */

        jdec.device = &dctx;

        /* We need mjpeg_input to find iodev.  Since tjpgd passes
         * jd->device to BOTH callbacks, we use a static global
         * for the input side.
         */

        ret = jd_decomp(&jdec, mjpeg_output, 0);
        if (ret == JDR_OK)
          {
            *out_w = jdec.width;
            *out_h = jdec.height;
            ok = 1;
          }
      }
  }

  ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);

err_streamoff:
  ioctl(fd, VIDIOC_STREAMOFF, (uintptr_t)&type);

err_free:
  if (buffers)
    {
      for (i = 0; i < (int)req.count; i++)
        {
          if (buffers[i].start) free(buffers[i].start);
        }
      free(buffers);
    }

errout:
  if (fd >= 0) close(fd);
  capture_uninitialize(CAM_DEV_PATH);
  return ok ? 0 : -EIO;
}

/****************************************************************************
 * Name: print_usage
 ****************************************************************************/

static void print_usage(const char *progname)
{
  printf("Usage: %s [options]\n", progname);
  printf("  -c         Camera mode: live preview + detection\n");
  printf("  -t <file>  Load test image from BMP file\n");
  printf("  -r <N>     Run N frames (0=forever, default 1 in non-camera)\n");
  printf("  -h         Show this help\n");
  printf("\nExamples:\n");
  printf("  %s                 # blank image test\n", progname);
  printf("  %s -c              # one-shot camera detection\n", progname);
  printf("  %s -c -r 0         # live preview (Ctrl-C to stop)\n", progname);
  printf("  %s -c -r 10        # camera, 10 frames\n", progname);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

extern "C" int main(int argc, char *argv[])
{
  const tflite::Model *model = nullptr;
  TfLiteTensor *input = nullptr;
  TfLiteTensor *output = nullptr;
  const char *image_path = nullptr;
  int iterations = 1;
  int use_camera = 0;
  int opt;

  /* Parse command line arguments */

  while ((opt = getopt(argc, argv, "ct:r:h")) != -1)
    {
      switch (opt)
        {
          case 'c':
            use_camera = 1;
            break;
          case 't':
            image_path = optarg;
            break;
          case 'r':
            iterations = atoi(optarg);
            break;
          case 'h':
          default:
            print_usage(argv[0]);
            return (opt == 'h') ? 0 : 1;
        }
    }

  tflite::InitializeTarget();

  printf("=== Person Detection Demo ===\n");
  fflush(stdout);

  /* Load model */

  model = tflite::GetModel(g_person_detect_model_data);
  if (model->version() != TFLITE_SCHEMA_VERSION)
    {
      fprintf(stderr, "ERROR: Model schema version mismatch\n");
      return 1;
    }

  tflite::MicroMutableOpResolver<5> op_resolver;
  op_resolver.AddConv2D(tflite::Register_CONV_2D_INT8());
  op_resolver.AddDepthwiseConv2D(tflite::Register_DEPTHWISE_CONV_2D_INT8());
  op_resolver.AddAveragePool2D(tflite::Register_AVERAGE_POOL_2D_INT8());
  op_resolver.AddReshape();
  op_resolver.AddSoftmax(tflite::Register_SOFTMAX_INT8());

  tflite::MicroInterpreter interpreter(
      model, op_resolver, g_tensor_arena, TENSOR_ARENA_SIZE);

  if (interpreter.AllocateTensors() != kTfLiteOk)
    {
      fprintf(stderr, "ERROR: AllocateTensors() failed\n");
      return 1;
    }

  input  = interpreter.input(0);
  output = interpreter.output(0);

  printf("Model loaded, arena: %zu/%d bytes\n",
         interpreter.arena_used_bytes(), TENSOR_ARENA_SIZE);
  fflush(stdout);

  /* =========================================================================
   * Camera live preview mode
   * ========================================================================= */

  if (use_camera)
    {
      int fb_ok = (fb_open() == OK);
      int person_score = 0;
      int no_person_score = 0;
      int detected = 0;
      int frame_count = 0;
      int run_forever = (iterations == 0);

      if (!fb_ok)
        {
          fprintf(stderr, "WARNING: LCD not available, output to console only\n");
        }

      printf("Live preview mode (frames: %s)\n",
             run_forever ? "infinite" : "limited");
      fflush(stdout);

      while (run_forever || frame_count < iterations)
        {
          uint32_t dec_w = 0;
          uint32_t dec_h = 0;

          /* Capture one frame and decode to RGB565 + grayscale */

          int ret = capture_and_decode(g_graybuf, g_rgbbuf, &dec_w, &dec_h);
          if (ret < 0)
            {
              fprintf(stderr, "ERROR: capture failed at frame %d\n",
                      frame_count);
              break;
            }

          frame_count++;

          /* Run inference on the grayscale image */

          memcpy(input->data.int8, g_graybuf, NUM_ROWS * NUM_COLS);

          if (interpreter.Invoke() == kTfLiteOk)
            {
              person_score = output->data.int8[PERSON_INDEX];
              no_person_score = output->data.int8[NOT_PERSON_IDX];
              detected = (person_score > no_person_score);
            }

          /* Overlay result on display */

          overlay_result(person_score, no_person_score, detected);

          /* Blit to LCD */

          if (fb_ok && dec_w > 0 && dec_h > 0)
            {
              uint32_t pw = (dec_w < CAM_WIDTH) ? dec_w : CAM_WIDTH;
              uint32_t ph = (dec_h < CAM_HEIGHT) ? dec_h : CAM_HEIGHT;
              fb_blit(pw, ph);
            }

          /* Console output */

          printf("\rFrame %d: %s (P:%d N:%d)   ",
                 frame_count,
                 detected ? "PERSON  " : "NO PERSON",
                 person_score, no_person_score);
          fflush(stdout);
        }

      printf("\nDone. %d frames processed.\n", frame_count);
      if (fb_ok) close(g_fbfd);
      return 0;
    }

  /* =========================================================================
   * Single image mode (BMP or blank)
   * ========================================================================= */

  printf("Single image mode\n");
  fflush(stdout);

  for (int iter = 0; iter < iterations; iter++)
    {
      if (image_path)
        {
          printf("Loading: %s\n", image_path);
          if (load_bmp_grayscale(image_path, input->data.int8) < 0)
            {
              return 1;
            }
        }
      else
        {
          printf("Using blank image\n");
          memset(input->data.int8, 0, NUM_ROWS * NUM_COLS);
        }

      if (interpreter.Invoke() != kTfLiteOk)
        {
          fprintf(stderr, "ERROR: Invoke() failed\n");
          return 1;
        }

      int8_t ps = output->data.int8[PERSON_INDEX];
      int8_t ns = output->data.int8[NOT_PERSON_IDX];

      printf("  notperson: %d  person: %d  -> %s\n",
             ns, ps, ps > ns ? "PERSON DETECTED" : "No person");
    }

  printf("Done.\n");
  return 0;
}

