/****************************************************************************
 * apps/examples/person_detection/person_detection_ssd_main.cc
 *
 * Person Detection with Bounding Box using SSD MobileNet V2
 *
 * Camera capture logic copied from uvc_test.
 * Uses SSD MobileNet V2 INT8 quantized model (COCO) for object detection.
 * Draws green bounding boxes around detected persons on the LCD preview.
 *
 * Usage:
 *   person_detection -c -r 0     # Live preview with bounding boxes
 *   person_detection -c -r 30    # 30 frames
 *   person_detection              # Blank image test
 ****************************************************************************/

#include <nuttx/config.h>

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cerrno>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/time.h>

#include <nuttx/video/video.h>
#include <nuttx/video/v4l2_cap.h>
#include <nuttx/video/fb.h>
#include <nuttx/lcd/lcd_dev.h>

#include "tensorflow/lite/micro/micro_interpreter.h"
#include "tensorflow/lite/micro/micro_log.h"
#include "tensorflow/lite/micro/micro_mutable_op_resolver.h"
#include "tensorflow/lite/micro/system_setup.h"
#include "tensorflow/lite/schema/schema_generated.h"

#include "ssd_model_data.inc"
#include "tjpgd.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* SSD MobileNet V2 input: 300x300x3 RGB INT8 */

#define SSD_INPUT_W    300
#define SSD_INPUT_H    300
#define SSD_INPUT_C    3
#define SSD_INPUT_SIZE (SSD_INPUT_W * SSD_INPUT_H * SSD_INPUT_C)

/* SSD outputs */

#define SSD_MAX_DETECTIONS 10

/* Display */

#define FB_DEV_PATH    "/dev/lcd0"
#define VIDEO_DEV_PATH "/dev/video"
#define DISP_WIDTH     320
#define DISP_HEIGHT    240
#define BUF_COUNT      6

/* Detection threshold */

#define DETECT_THRESHOLD 0.5f

/* Person class ID in COCO dataset */

#define COCO_PERSON_CLASS 0

/* Tensor arena size — SSD needs more than the classifier */

#define TENSOR_ARENA_SIZE (1024 * 1024)

/* Font */

#define FONT_W  5
#define FONT_H  7
#define FONT_SCALE 2

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct v_buffer
{
  uint8_t *start;
  uint32_t length;
};

struct mjpeg_iodev_s
{
  const uint8_t *data;
  size_t         len;
  size_t         pos;
};

/****************************************************************************
 * tjpgd callbacks (copied from uvc_test)
 ****************************************************************************/

static size_t mjpeg_input(JDEC *jd, uint8_t *buff, size_t nbyte)
{
  struct mjpeg_iodev_s *io = (struct mjpeg_iodev_s *)jd->device;
  size_t avail = io->len - io->pos;
  if (nbyte > avail) nbyte = avail;
  if (buff) memcpy(buff, io->data + io->pos, nbyte);
  io->pos += nbyte;
  return nbyte;
}

/* Output callback: decode to RGB565 display buffer */

static uint16_t g_rgbbuf[DISP_WIDTH * DISP_HEIGHT];

static int mjpeg_output(JDEC *jd, void *bitmap, JRECT *rect)
{
  uint8_t *src = (uint8_t *)bitmap;
  uint32_t x;
  uint32_t y;
  uint32_t cpw = jd->width < DISP_WIDTH ? jd->width : DISP_WIDTH;

  for (y = rect->top; y <= rect->bottom && y < DISP_HEIGHT; y++)
    {
      for (x = rect->left; x <= rect->right && x < DISP_WIDTH; x++)
        {
          uint8_t b = *src++;
          uint8_t g = *src++;
          uint8_t r = *src++;
          g_rgbbuf[y * cpw + x] =
            ((r & 0xf8) << 8) | ((g & 0xfc) << 3) | (b >> 3);
        }

      if (rect->right >= DISP_WIDTH)
        src += (rect->right - DISP_WIDTH + 1) * 3;
    }

  return 1;
}

/* Output callback: decode to SSD input buffer (300x300 RGB INT8) */

static int8_t g_ssd_input[SSD_INPUT_SIZE];

static int mjpeg_output_ssd(JDEC *jd, void *bitmap, JRECT *rect)
{
  uint8_t *src = (uint8_t *)bitmap;
  uint32_t x;
  uint32_t y;
  uint32_t src_w = jd->width;
  uint32_t src_h = jd->height;

  for (y = rect->top; y <= rect->bottom; y++)
    {
      for (x = rect->left; x <= rect->right; x++)
        {
          uint8_t b = *src++;
          uint8_t g = *src++;
          uint8_t r = *src++;

          /* Map to 300x300 grid */

          int dx = (int)(x * SSD_INPUT_W / src_w);
          int dy = (int)(y * SSD_INPUT_H / src_h);
          if (dx >= SSD_INPUT_W) dx = SSD_INPUT_W - 1;
          if (dy >= SSD_INPUT_H) dy = SSD_INPUT_H - 1;

          int idx = (dy * SSD_INPUT_W + dx) * SSD_INPUT_C;
          g_ssd_input[idx + 0] = static_cast<int8_t>(r - 128);
          g_ssd_input[idx + 1] = static_cast<int8_t>(g - 128);
          g_ssd_input[idx + 2] = static_cast<int8_t>(b - 128);
        }
    }

  return 1;
}

