/****************************************************************************
 * Drawing Helpers
 ****************************************************************************/

static void draw_pixel(int x, int y, uint16_t color)
{
  if (x >= 0 && x < DISP_WIDTH && y >= 0 && y < DISP_HEIGHT)
    g_rgbbuf[y * DISP_WIDTH + x] = color;
}

static void draw_hline(int x0, int x1, int y, uint16_t color)
{
  for (int x = x0; x <= x1; x++)
    draw_pixel(x, y, color);
}

static void draw_vline(int x, int y0, int y1, uint16_t color)
{
  for (int y = y0; y <= y1; y++)
    draw_pixel(x, y, color);
}

/* Draw a rectangle outline (2px thick for visibility) */

static void draw_rect(int x0, int y0, int x1, int y1, uint16_t color)
{
  draw_hline(x0, x1, y0, color);
  draw_hline(x0, x1, y0 + 1, color);
  draw_hline(x0, x1, y1, color);
  draw_hline(x0, x1, y1 - 1, color);
  draw_vline(x0, y0, y1, color);
  draw_vline(x0 + 1, y0, y1, color);
  draw_vline(x1, y0, y1, color);
  draw_vline(x1 - 1, y0, y1, color);
}

static void draw_filled_rect(int x0, int y0, int x1, int y1,
                              uint16_t color)
{
  for (int y = y0; y <= y1; y++)
    for (int x = x0; x <= x1; x++)
      draw_pixel(x, y, color);
}

static void draw_char(int x, int y, char c, uint16_t color, int scale)
{
  if (c < 32 || c > 90) return;
  int idx = c - 32;
  if (idx < 0 || idx >= (int)(sizeof(g_font5x7) / FONT_W)) return;
  const uint8_t *glyph = g_font5x7[idx];
  for (int col = 0; col < FONT_W; col++)
    {
      uint8_t line = glyph[col];
      for (int row = 0; row < FONT_H; row++)
        if (line & (1 << row))
          for (int sy = 0; sy < scale; sy++)
            for (int sx = 0; sx < scale; sx++)
              draw_pixel(x + col * scale + sx, y + row * scale + sy, color);
    }
}

static void draw_string(int x, int y, const char *str,
                         uint16_t color, int scale)
{
  while (*str)
    {
      draw_char(x, y, *str, color, scale);
      x += (FONT_W + 1) * scale;
      str++;
    }
}

/****************************************************************************
 * Framebuffer
 ****************************************************************************/

static int fb_open(void)
{
  g_fbfd = open(FB_DEV_PATH, O_RDWR);
  if (g_fbfd < 0)
    {
      printf("ERROR: open %s failed: %d\n", FB_DEV_PATH, errno);
      return -errno;
    }

  int ret = ioctl(g_fbfd, LCDDEVIO_GETVIDEOINFO, (uintptr_t)&g_vinfo);
  if (ret < 0)
    {
      printf("ERROR: LCDDEVIO_GETVIDEOINFO failed: %d\n", errno);
      close(g_fbfd);
      g_fbfd = -1;
      return -errno;
    }

  printf("LCD: %ux%u fmt=%u\n", g_vinfo.xres, g_vinfo.yres, g_vinfo.fmt);
  return OK;
}

static void fb_blit(uint32_t w, uint32_t h)
{
  struct lcddev_area_s area;
  memset(&area, 0, sizeof(area));
  area.row_start = 0;
  area.row_end   = h - 1;
  area.col_start = 0;
  area.col_end   = w - 1;
  area.stride    = w * 2;
  area.data      = (FAR uint8_t *)g_rgbbuf;
  ioctl(g_fbfd, LCDDEVIO_PUTAREA, (uintptr_t)&area);
}

/****************************************************************************
 * print_usage
 ****************************************************************************/

static void print_usage(const char *progname)
{
  printf("Usage: %s [options]\n", progname);
  printf("  -c         Camera mode with bounding boxes\n");
  printf("  -r <N>     N frames (0=forever)\n");
  printf("  -h         Help\n");
}

/****************************************************************************
 * main
 ****************************************************************************/

extern "C" int main(int argc, char *argv[])
{
  const tflite::Model *model = nullptr;
  TfLiteTensor *input = nullptr;
  int iterations = 1;
  int use_camera = 0;
  int opt;

  while ((opt = getopt(argc, argv, "cr:h")) != -1)
    switch (opt)
      {
        case 'c': use_camera = 1; break;
        case 'r': iterations = atoi(optarg); break;
        default: print_usage(argv[0]); return (opt == 'h') ? 0 : 1;
      }

  tflite::InitializeTarget();
  printf("=== Person Detection (SSD) ===\n");
  fflush(stdout);

  /* Load SSD model */

  model = tflite::GetModel(g_ssd_model_data);
  if (model->version() != TFLITE_SCHEMA_VERSION)
    { printf("ERROR: Model version mismatch\n"); return 1; }

  /* Register all operators needed by SSD MobileNet V2 */

  static tflite::MicroMutableOpResolver<20> op_resolver;
  op_resolver.AddConv2D();
  op_resolver.AddDepthwiseConv2D();
  op_resolver.AddMaxPool2D();
  op_resolver.AddAveragePool2D();
  op_resolver.AddReshape();
  op_resolver.AddSoftmax();
  op_resolver.AddConcatenation();
  op_resolver.AddAdd();
  op_resolver.AddMul();
  op_resolver.AddLogistic();
  op_resolver.AddQuantize();
  op_resolver.AddDequantize();
  op_resolver.AddFullyConnected();
  op_resolver.AddCustom("TFLite_Detection_PostProcess",
                        tflite::Register_DETECTION_POSTPROCESS());

  tflite::MicroInterpreter interpreter(
      model, op_resolver, g_tensor_arena, TENSOR_ARENA_SIZE);

  if (interpreter.AllocateTensors() != kTfLiteOk)
    { printf("ERROR: AllocateTensors failed (arena too small?)\n"); return 1; }

  input = interpreter.input(0);

  printf("Model loaded, input: %dx%dx%d, arena: %zu/%d bytes\n",
         input->dims->data[1], input->dims->data[2], input->dims->data[3],
         interpreter.arena_used_bytes(), TENSOR_ARENA_SIZE);
  fflush(stdout);

  /* =========================================================================
   * Camera mode with bounding boxes
   * ========================================================================= */

  if (use_camera)
    {
      struct v4l2_format fmt;
      struct v4l2_requestbuffers req;
      struct v4l2_buffer buf;
      struct v_buffer *buffers;
      enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      int fd;
      int ret;
      int i;
      int frames = 0;
      int run_forever = (iterations == 0);
      int fb_ok = (fb_open() == OK);

      /* Camera setup (same as uvc_test) */

      capture_initialize(VIDEO_DEV_PATH);
      fd = open(VIDEO_DEV_PATH, O_RDWR);
      if (fd < 0)
        { printf("ERROR: open %s: %d\n", VIDEO_DEV_PATH, errno); return 1; }

      memset(&fmt, 0, sizeof(fmt));
      fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      fmt.fmt.pix.width = DISP_WIDTH;
      fmt.fmt.pix.height = DISP_HEIGHT;
      fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
      fmt.fmt.pix.field = V4L2_FIELD_NONE;
      ioctl(fd, VIDIOC_S_FMT, (uintptr_t)&fmt);
      if (fmt.fmt.pix.sizeimage == 0)
        fmt.fmt.pix.sizeimage = DISP_WIDTH * DISP_HEIGHT * 2;

      memset(&req, 0, sizeof(req));
      req.count = BUF_COUNT;
      req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      req.memory = V4L2_MEMORY_USERPTR;
      ioctl(fd, VIDIOC_REQBUFS, (uintptr_t)&req);

      buffers = (struct v_buffer *)malloc(req.count * sizeof(struct v_buffer));
      for (i = 0; i < (int)req.count; i++)
        {
          buffers[i].length = fmt.fmt.pix.sizeimage;
          buffers[i].start = (uint8_t *)memalign(64, buffers[i].length);
          memset(&buf, 0, sizeof(buf));
          buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
          buf.memory = V4L2_MEMORY_USERPTR;
          buf.index = i;
          buf.m.userptr = (uintptr_t)buffers[i].start;
          buf.length = buffers[i].length;
          ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);
        }

      ioctl(fd, VIDIOC_STREAMON, (uintptr_t)&type);
      printf("Camera streaming (SSD %dx%d input)\n", SSD_INPUT_W, SSD_INPUT_H);
      fflush(stdout);

      /* Main loop */

      while (run_forever || frames < iterations)
        {
          struct timeval t0, t1, t2, t3;
          gettimeofday(&t0, NULL);

          /* DQBUF + snapshot (same as uvc_test) */

          memset(&buf, 0, sizeof(buf));
          buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
          buf.memory = V4L2_MEMORY_USERPTR;
          ret = ioctl(fd, VIDIOC_DQBUF, (uintptr_t)&buf);
          if (ret < 0) break;

          uint32_t n = buf.bytesused;
          if (n > sizeof(g_framecopy)) n = sizeof(g_framecopy);
          memcpy(g_framecopy, (const void *)buf.m.userptr, n);
          ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);

          gettimeofday(&t1, NULL);

          /* Decode JPEG twice: once for display, once for SSD input */

          {
            static uint8_t jdwork[4096];
            struct mjpeg_iodev_s iodev;

            /* Pass 1: decode to RGB565 display buffer */

            {
              JDEC jdec;
              iodev.data = g_framecopy;
              iodev.len  = n;
              iodev.pos  = 0;
              if (jd_prepare(&jdec, mjpeg_input, jdwork,
                             sizeof(jdwork), &iodev) == JDR_OK)
                jd_decomp(&jdec, mjpeg_output, 0);
            }

            /* Pass 2: decode to SSD input buffer (300x300 RGB INT8) */

            {
              JDEC jdec;
              iodev.data = g_framecopy;
              iodev.len  = n;
              iodev.pos  = 0;
              memset(g_ssd_input, 0, sizeof(g_ssd_input));
              if (jd_prepare(&jdec, mjpeg_input, jdwork,
                             sizeof(jdwork), &iodev) == JDR_OK)
                jd_decomp(&jdec, mjpeg_output_ssd, 0);
            }
          }

          gettimeofday(&t2, NULL);

          /* Run SSD inference */

          memcpy(input->data.int8, g_ssd_input, SSD_INPUT_SIZE);

          int num_persons = 0;
          if (interpreter.Invoke() == kTfLiteOk)
            {
              /* SSD output tensors:
               *   0: boxes   [1, N, 4] float (ymin, xmin, ymax, xmax) [0,1]
               *   1: classes [1, N]    float (class ID)
               *   2: scores  [1, N]    float (confidence)
               *   3: num_detections [1] float
               */

              TfLiteTensor *out_boxes  = interpreter.output(0);
              TfLiteTensor *out_classes = interpreter.output(1);
              TfLiteTensor *out_scores = interpreter.output(2);
              TfLiteTensor *out_num    = interpreter.output(3);

              int num_det = (int)out_num->data.f[0];
              if (num_det > SSD_MAX_DETECTIONS)
                num_det = SSD_MAX_DETECTIONS;

              for (int d = 0; d < num_det; d++)
                {
                  float score = out_scores->data.f[d];
                  int cls = (int)out_classes->data.f[d];

                  /* Only draw boxes for "person" class (COCO ID 0)
                   * with confidence above threshold */

                  if (cls == COCO_PERSON_CLASS && score >= DETECT_THRESHOLD)
                    {
                      float ymin = out_boxes->data.f[d * 4 + 0];
                      float xmin = out_boxes->data.f[d * 4 + 1];
                      float ymax = out_boxes->data.f[d * 4 + 2];
                      float xmax = out_boxes->data.f[d * 4 + 3];

                      /* Map normalized [0,1] to screen coordinates */

                      int sx1 = (int)(xmin * DISP_WIDTH);
                      int sy1 = (int)(ymin * DISP_HEIGHT);
                      int sx2 = (int)(xmax * DISP_WIDTH);
                      int sy2 = (int)(ymax * DISP_HEIGHT);

                      /* Clamp */

                      if (sx1 < 0) sx1 = 0;
                      if (sy1 < 0) sy1 = 0;
                      if (sx2 >= DISP_WIDTH)  sx2 = DISP_WIDTH - 1;
                      if (sy2 >= DISP_HEIGHT) sy2 = DISP_HEIGHT - 1;

                      /* Draw green bounding box */

                      uint16_t green = ((0 << 11) | (63 << 5) | 0);
                      draw_rect(sx1, sy1, sx2, sy2, green);

                      /* Draw label with confidence */

                      char label[16];
                      snprintf(label, sizeof(label), "P:%d%%",
                               (int)(score * 100));

                      /* Label background */

                      int lw = (FONT_W + 1) * FONT_SCALE * strlen(label);
                      int lh = FONT_H * FONT_SCALE;
                      draw_filled_rect(sx1, sy1 - lh - 2, sx1 + lw, sy1 - 1,
                                       green);

                      /* Label text */

                      draw_string(sx1, sy1 - lh - 1, label,
                                  0xFFFF, FONT_SCALE);

                      num_persons++;
                    }
                }
            }

          gettimeofday(&t3, NULL);

          /* Blit to LCD */

          if (fb_ok)
            fb_blit(DISP_WIDTH, DISP_HEIGHT);

          frames++;

          /* Timing every 10 frames */

          if (frames % 10 == 0)
            {
              int cap_us   = (t1.tv_sec - t0.tv_sec) * 1000000 +
                             (t1.tv_usec - t0.tv_usec);
              int decode_us = (t2.tv_sec - t1.tv_sec) * 1000000 +
                              (t2.tv_usec - t1.tv_usec);
              int infer_us  = (t3.tv_sec - t2.tv_sec) * 1000000 +
                              (t3.tv_usec - t2.tv_usec);
              int total_us  = (t3.tv_sec - t0.tv_sec) * 1000000 +
                              (t3.tv_usec - t0.tv_usec);
              printf("\nTiming: cap=%dms decode=%dms infer=%dms total=%dms "
                     "(%dfps) persons=%d\n",
                     cap_us/1000, decode_us/1000, infer_us/1000,
                     total_us/1000, total_us > 0 ? 1000000/total_us : 0,
                     num_persons);
            }

          printf("\rFrame %d: %d person(s) detected   ",
                 frames, num_persons);
          fflush(stdout);
        }

      printf("\nDone. %d frames.\n", frames);

      /* Cleanup */

      ioctl(fd, VIDIOC_STREAMOFF, (uintptr_t)&type);
      for (i = 0; i < (int)req.count; i++)
        if (buffers[i].start) free(buffers[i].start);
      free(buffers);
      close(fd);
      if (fb_ok) close(g_fbfd);
      return 0;
    }

  /* Single image mode not supported for SSD */

  printf("Use -c for camera mode with SSD bounding boxes.\n");
  return 0;
}

