122	  TfLiteType input_type = input_tensor->type;
123	  TfLiteTensor* output_tensor =
124	      micro_context->AllocateTempOutputTensor(node, kOutputTensor);
125	  TF_LITE_ENSURE(context, output_tensor != nullptr);
126	  TfLiteType output_type = output_tensor->type;
127	
