129	  micro_context->DeallocateTempTfLiteTensor(output_tensor);
130	
131	  // Check activation and input type
132	  TF_LITE_ENSURE_EQ(context, params->activation, kTfLiteActNone);
133	  TF_LITE_ENSURE(context,
134	                 input_type == kTfLiteFloat32 || input_type == kTfLiteInt8 ||
135	                     input_type == kTfLiteInt16 || input_type == kTfLiteInt32 ||
136	                     input_type == kTfLiteInt64 || input_type == kTfLiteBool);
137	
138	  // Output type must match input type
139	  TF_LITE_ENSURE_EQ(context, output_type, input_type);
